//! Jukugo (熟語) table — JP compound words with reading + freq.
//!
//! Generated by `tools/nihongo/build_jukugo_rs.py` from the supplemental TSV.
//! DO NOT edit by hand — re-run the script. Corrections go to the TSV.
//!
//! Codepoint-identity-with-SC constraint REMOVED — Inputx's JP plugin is
//! professional-grade now, so shinjitai-only compounds (経済/愛情/電話/…)
//! are first-class.

#[derive(Copy, Clone, Debug)]
pub struct JukugoEntry {
    pub reading: &'static str,
    pub kanji: &'static str,
    pub freq: u32,
}

const fn j(r: &'static str, k: &'static str, f: u32) -> JukugoEntry {
    JukugoEntry { reading: r, kanji: k, freq: f }
}

pub fn lookup_by_reading(romaji: &str) -> impl Iterator<Item = (&'static str, u32)> + '_ {
    JUKUGO_TABLE.iter().filter_map(move |e| {
        if e.reading == romaji { Some((e.kanji, e.freq)) } else { None }
    })
}

/// Prefix-prediction lookup: jukugo whose reading STARTS WITH `romaji` but is
/// longer (the user is mid-typing toward it — shinjuk → 新宿/しんじゅく). Yields
/// `(kanji, freq, reading_len_bytes)` so the composite layer can score by
/// proximity = typed_len / reading_len. Excludes exact matches (== reading),
/// which `lookup_by_reading` already covers. Linear scan over JUKUGO_TABLE
/// (~27k; ~27µs measured, same as exact lookup).
pub fn lookup_by_reading_prefix(romaji: &str) -> impl Iterator<Item = (&'static str, u32, usize)> + '_ {
    JUKUGO_TABLE.iter().filter_map(move |e| {
        if e.reading.len() > romaji.len() && e.reading.starts_with(romaji) {
            Some((e.kanji, e.freq, e.reading.len()))
        } else {
            None
        }
    })
}

